package net.minecraft.server;import net.minecraft.server.level.*;import net.minecraft.world.level.saveddata.*;import java.util.*;import java.util.function.*;import net.minecraft.nbt.*;public class MinecraftServer {private final java.util.UUID testWorldId=java.util.UUID.randomUUID();public final ServerLevel world=new ServerLevel(this);public ServerLevel overworld(){return world;}public java.util.List<ServerLevel> getAllLevels(){return java.util.List.of(world);}public MinecraftServer getServer(){return this;}public java.nio.file.Path getWorldPath(net.minecraft.world.level.storage.LevelResource root){return java.nio.file.Path.of(System.getProperty("java.io.tmpdir"),"kingdom-harness-"+testWorldId);}public final DataStore store=new DataStore();public static class DataStore {public final Map<String,SavedData> values=new HashMap<>();public <T extends SavedData> T computeIfAbsent(Function<CompoundTag,T> load,Supplier<T> init,String key){return (T)values.computeIfAbsent(key,k->init.get());}}}